    {
      "label": "A",
      "phrases": [
        {
          "id": "V1-01",
          "zh": "草丛深处开 一朵无名花"
        },
        {
          "id": "V1-02",
          "zh": "若只是花开 无人来欣赏"
        },
        {
          "id": "V1-03",
          "zh": "只是迎着风 轻轻地摇晃"
        },
        {
          "id": "V1-04",
          "zh": "就这样随风摇晃 本来也足够"
        }
      ]
    },
    {
      "label": "B",
      "phrases": [
        {
          "id": "V1-01",
          "zh": "草丛中啊 名字无人知"
        },
        {
          "id": "V1-02",
          "zh": "静静绽放着 若是野花时"
        },
        {
          "id": "V1-03",
          "zh": "只需迎着那 清风拂过来"
        },
        {
          "id": "V1-04",
          "zh": "轻轻摇曳着 那样便足矣"
        }
      ]
    }
  ]
}

